// «12.000» → «12,000»: los miles, en inglés con coma (los números del juego salen con formatoNumero, a la española)
const conMiles = numero => numero.replace(/\./g, ',');
const PATRONES_EN = [
  [/^(Escaramuza|Flechas de fuego): (sí|no)$/, (m, que, valor) => (que === 'Escaramuza' ? 'Skirmish' : 'Fire arrows') + ': ' + (valor === 'sí' ? 'on' : 'off')],
  // ---- inicio, menú, tienda ----
  [/^Reino guardado:$/, 'Saved kingdom:'],
  [/^, (.+?)( · .+)? · (\d+) victorias, (\d+) derrotas$/, (m, rey, rama, v, d) => `, ${rey}${rama || ''} · ${v} victories, ${d} defeats`],
  [/^(.+?)( · .+)? · (\d+) victorias, (\d+) derrotas$/, (m, a, b, v, d) => `${a}${b || ''} · ${v} victories, ${d} defeats`],
  [/^Blasón de (.+)$/, 'Coat of arms of $1'],
  [/^Blasón importado: (\d+) capas, silueta «(.+)»\.$/, 'Imported coat of arms: $1 layers, «$2» shape.'],
  [/^(\d+) soldados por unidad · vida ([\d.,]+), daño ([\d.,]+), velocidad ([\d.,]+)(, (\d+) andanadas)?( · .+)?$/, (m, s, v, d, vel, x, a, bonos) => `${s} soldiers per unit · health ${v}, damage ${d}, speed ${vel}${a ? `, ${a} volleys` : ''}${bonos ? bonos.replace(/vida/g, 'health').replace(/daño/g, 'damage').replace(/velocidad/g, 'speed').replace(/precio/g, 'price') : ''}`],
  [/^(\d+) soldados por unidad$/, '$1 soldiers per unit'],
  [/^(.+): ×([\d.]+) vida y daño, ×([\d.]+) moral$/, '$1: ×$2 health and damage, ×$3 morale'],
  [/^([\d.]+) oro$/, (m, n) => conMiles(n) + ' gold'],
  [/^(\d{1,3}(?:\.\d{3})+)$/, (m, n) => conMiles(n)],          // un precio suelto (2.000) con los miles a la inglesa
  [/^disponibles · ejército: (\d+) unidades, (\d+) soldados$/, 'available · army: $1 units, $2 soldiers'],
  [/^(\d+) soldados · ([\d.]+)$/, '$1 soldiers · $2'],
  [/^Añadir una unidad de (.+)$/, 'Add a unit of $1'],
  [/^Enemigo: (\d+) unidades, (\d+) soldados, valor ([\d.]+) · tu ejército: (\d+) unidades, (\d+) soldados, valor ([\d.]+)(?: \(el enemigo vale (\d+) % del tuyo\))?$/, (m, a, b, c, d, e, f, g) => `Enemy: ${a} units, ${b} soldiers, value ${c} · your army: ${d} units, ${e} soldiers, value ${f}${g ? ` (the enemy is worth ${g} % of yours)` : ''}`],
  // ---- batalla ----
  [/^Contra$/, 'Against'],
  [/^\((ejército elegido, IA )?(.+), actitud (.+)\) · (\d+) unidades enemigas(?: · arte propio: (\d+) tipos)?$/, (m, elegido, dif, act, n, arte) => `(${elegido ? 'chosen army, AI ' : ''}${dif}, ${act} stance) · ${n} enemy units${arte ? ` · custom art: ${arte} types` : ''}`],
  [/^Partida en red:$/, 'Online match:'],
  [/^\((izquierda|derecha), (.+)\) contra$/, (m, lado, rama) => `(${lado === 'izquierda' ? 'left' : 'right'}, ${rama}) vs`],
  [/^· el enemigo espera tu ataque$/, '· the enemy awaits your attack'],
  [/^· el enemigo no aguanta más tus andanadas y pasa al ataque$/, '· the enemy can take no more of your volleys and attacks'],
  [/^· el enemigo se cansa de esperar y pasa al ataque$/, '· the enemy grows tired of waiting and attacks'],
  [/^· el enemigo se ve vencedor y pasa al ataque$/, '· the enemy smells victory and attacks'],
  [/^· ¡desincronizado del servidor!$/, '· out of sync with the server!'],
  [/^(Tus soldados|Soldados enemigos) en el campo \/ al empezar$/, (m, q) => `${q === 'Tus soldados' ? 'Your soldiers' : 'Enemy soldiers'} on the field / at the start`],
  [/^(\d+) en pie(?:, (\d+) en retirada)?(?:, (\d+) huyendo)?$/, (m, a, r, h) => `${a} standing${r ? `, ${r} retreating` : ''}${h ? `, ${h} fleeing` : ''}`],
  [/^(\d+) muertos(?:, (\d+) escapados del campo)?$/, (m, a, e) => `${a} dead${e ? `, ${e} escaped the field` : ''}`],
  [/^(\d+) unidades$/, '$1 units'],
  [/^· (\d+) soldados$/, '· $1 soldiers'],
  [/^(\d+)\/(\d+) · moral (\d+)(?: \((.+)\))? · (.+)$/, (m, a, b, mo, f, o) => `${a}/${b} · morale ${mo}${f ? ` (${traducirFactores(f)})` : ''} · ${traducirOrden(o)}`],
  [/^moral (\d+)(?: \((.+)\))?$/, (m, mo, f) => `morale ${mo}${f ? ` (${traducirFactores(f)})` : ''}`],
  [/^Quedan (\d+):(\d\d)( \(en espera\))?$/, (m, a, b, e) => `${a}:${b} left${e ? ' (on hold)' : ''}`],
  [/^Pausa pedida por (.+)\. Sigue sola en (\d+:\d\d); cualquiera puede quitarla con P o ▶\.$/, 'Pause requested by $1. Resumes by itself in $2; anyone can lift it with P or ▶.'],
  [/^(.+) ha quitado la pausa\.$/, '$1 lifted the pause.'],
  [/^(.+) se ha desconectado\. Se le espera (\d+) s; si no vuelve, ganas la batalla\.$/, '$1 disconnected. Waiting $2 s for them; if they do not return, you win the battle.'],
  [/^Conexión perdida con el servidor\. Reconectando… \((\d+) s\)$/, 'Connection to the server lost. Reconnecting… ($1 s)'],
  [/^Sin pausa: (.+)$/, (m, motivo) => 'No pause: ' + traducirTexto(motivo)],
  [/^(.+) prefiere seguir\.$/, '$1 prefers to keep fighting.'],
  [/^Ya has usado tus (\d+) pausas\.$/, 'You have already used your $1 pauses.'],
  // ---- resultado ----
  [/^Unidad destacada: (.+), (\d+) bajas causadas\.$/, (m, u, n) => `Standout unit: ${traducirTexto(u)}, ${n} kills.`],
  [/^Nuevo rasgo: (.+)$/, (m, r) => 'New trait: ' + traducirTexto(r)],
  [/^Duración: (\d+) s · semilla (\d+) · marcador del reino: (\d+) victorias, (\d+) derrotas$/, 'Duration: $1 s · seed $2 · kingdom record: $3 victories, $4 defeats'],
  [/^Partida en red · duración: (\d+) s · semilla (\d+)\. Las partidas en red no cambian tu reino\.$/, 'Online match · duration: $1 s · seed $2. Online matches do not change your kingdom.'],
  [/^(.+) se ha rendido\.$/, '$1 surrendered.'],
  [/^(.+) ha anunciado dos veces un resultado falso\.$/, '$1 announced a false result twice.'],
  [/^La partida de (.+) se ha desviado de la del servidor varias veces\.$/, "$1's game drifted from the server's several times."],
  [/^(.+) ha abandonado la batalla\.$/, '$1 left the battle.'],
  [/^El ejército de (.+) ha sido destruido o ha huido del campo\.$/, '$1’s army has been destroyed or has fled the field.'],
  [/^Puntos: muertos de cada bando \(claros los tuyos, rojos los de (.+)\)\. Marca final de cada unidad: punto si quedó en pie, aspa si fue aniquilada, flecha si huyó; ★ la guardia del general\.$/, 'Dots: the dead of each side (light yours, red $1’s). Final mark of each unit: dot if it stood, cross if annihilated, arrow if it fled; ★ the general’s guard.'],
  [/^(.+) \((leva|milicia|hombres de armas|veteranos)\)$/, (m, t, n) => `${traducirTexto(t)} (${({ leva: 'levy', milicia: 'militia', 'hombres de armas': 'men-at-arms', veteranos: 'veterans' })[n]})`],
  [/^Guardia del rey ([^·:]+)$/, 'Guard of King $1'],
  [/^Guardia de ([^·:]+)$/, 'Guard of $1'],
  [/^(.+) ★$/, (m, n) => traducirTexto(n) + ' ★'],
  // ---- discurso ----
  [/^Soldados de (.+?): (.+)$/, (m, reino, resto) => `Soldiers of ${reino}: ${traducirTexto(resto)}`],
  [/^Enfrente está (.+)\.$/, 'Opposite us stands $1.'],
  [/^¡Por (.+)!$/, 'For $1!'],
  // ---- multijugador ----
  [/^Conectado como (.+) · (.+)$/, 'Connected as $1 · $2'],
  [/^No se pudo conectar con (.+?)\.(?: ¿Está encendido el servidor\? \(cd servidor && npm start\))?$/, (m, url) => `Could not connect to ${url}.` + (/¿Está/.test(m) ? ' Is the server running? (cd servidor && npm start)' : '')],
  [/^(Dirección no válida\.|El servidor no responde\.) ¿Está encendido el servidor\? \(cd servidor && npm start\)$/, (m, e) => traducirTexto(e) + ' Is the server running? (cd servidor && npm start)'],
  [/^· anfitrión (.+) · (\d+)\/(\d+)$/, '· host $1 · $2/$3'],
  [/^Código para invitar:$/, 'Invite code:'],
  [/^Clima: (.+?)(?: · Mapa: (.+))?$/, (m, c, mp) => `Weather: ${traducirTexto(c)}${mp ? ' · Map: ' + traducirTexto(mp) : ''}`],
  [/^([\d.]+) de oro$/, (m, n) => conMiles(n) + ' gold'],
  [/^([\d.]+) de ([\d.]+) de oro gastado · quedan (-?[\d.]+)$/, (m, a, b, c) => `${conMiles(a)} of ${conMiles(b)} gold spent · ${conMiles(c)} left`],
  [/^Los dos estáis listos\. Juegas en el lado (izquierdo|derecho); clima: (.+)\. Elegid rama y ejército con ([\d.]+) de oro\.$/, (m, lado, c, oro) => `You are both ready. You play on the ${lado === 'izquierdo' ? 'left' : 'right'} side; weather: ${traducirTexto(c)}. Choose faction and army with ${conMiles(oro)} gold.`],
  [/^Clima: (.+) · ([\d.]+) de oro por jugador · semilla (\d+)$/, (m, c, oro, s) => `Weather: ${traducirTexto(c)} · ${conMiles(oro)} gold per player · seed ${s}`],
  [/^\((izquierda|derecha)\) · (.+) · ([\d.]+) de oro$/, (m, lado, rama, oro) => `(${lado === 'izquierda' ? 'left' : 'right'}) · ${rama} · ${conMiles(oro)} gold`],
  [/^(\d+) × (.+)$/, (m, n, u) => `${n} × ${traducirTexto(u)}`],
  [/^\((\d+) soldados\)$/, '($1 soldiers)'],
  [/^Sala de (.+)$/, '$1’s room'],
  // mensajes del servidor con datos
  [/^(.+) ha entrado en la sala$/, '$1 joined the room'],
  [/^(.+) ha salido de la sala(; la preparación se cancela)?$/, (m, n, c) => `${n} left the room${c ? '; preparation is cancelled' : ''}`],
  [/^Presupuesto: ([\d.]+) de oro por jugador$/, (m, n) => 'Budget: ' + conMiles(n) + ' gold per player'],
  [/^Ejército no válido: (.+)$/, (m, motivo) => 'Invalid army: ' + traducirTexto(motivo)],
  [/^Como mucho (\d+) unidades\.$/, 'At most $1 units.'],
  [/^Como mucho (\d+) unidades de (.+)\.$/, (m, n, nombre) => `At most ${n} units of ${TEXTOS_EN[nombre] || nombre}.`],
  [/^Máximo (\d+) por ejército$/, 'At most $1 per army'],
  [/^Tropa no disponible para esa rama: (.+)$/, 'Troop not available for that faction: $1'],
  [/^Cuesta (\d+) y el presupuesto es (\d+)\.$/, 'It costs $1 and the budget is $2.'],
  [/^Orden desconocida: (.+)$/, 'Unknown command: $1'],
  [/^(.+) contra (.+)$/, '$1 vs $2'],
  // ---- panel, tarjetas y títulos ----
  [/^(.+?): (\d+)\/(\d+) · moral (\d+)(?: \((.+?)\))? · fatiga (\d+) % · cohesión (\d+) %(.*)$/, (m, nombre, a, b, mo, f, fa, co, resto) => `${traducirTexto(nombre)}: ${a}/${b} · morale ${mo}${f ? ` (${traducirFactores(f)})` : ''} · fatigue ${fa} % · cohesion ${co} %${resto.split(' · ').map(p => p ? traducirParte(p) : p).join(' · ')}`],
  [/^Moral (\d+) de (\d+) \(huye por debajo de (\d+); (\d+) con el general cerca\)\.$/, 'Morale $1 of $2 (flees below $3; $4 with the general nearby).'],
  [/^· (.+) ([+−]\d+)$/, (m, f, v) => `· ${traducirTexto(f)} ${v}`],
  [/^(.+) · clic: seleccionar \(Mayús añade\) · doble clic: ir a la unidad · arrastrar: cambiar el orden$/, (m, n) => `${traducirTexto(n)} · click: select (Shift adds) · double click: go to the unit · drag: change the order`],
  [/^Para (.+?)\.( Ninguna unidad seleccionada puede usarla\.)?$/, (m, quien, ninguna) => `For ${traducirTexto(quien)}.${ninguna ? ' No selected unit can use it.' : ''}`],
  [/^(\d+) andanadas$/, '$1 volleys'],
  [/^Moral (\d+) de (\d+)(?:: (.+))?$/, (m, a, b, f) => `Morale ${a} of ${b}${f ? ': ' + traducirFactores(f) : ''}`],
  [/^· (atacando|moviéndose|disparando|cargando|huyendo|alto|en cuerpo a cuerpo|en retirada ordenada)( a la carrera| al paso)?$/, (m, o, marcha) => '· ' + traducirOrden(o + (marcha || ''))],
  // ---- moral: factores con números ----
  [/^bajas \((\d+) %\)$/, 'losses ($1 %)'],
  [/^apoyo de (\d+) filas?$/, (m, n) => `support of ${n} rank${n === '1' ? '' : 's'}`],
];
// orden de una unidad en el resumen del panel («alto», «atacando a la carrera»…)
function traducirOrden(texto) {
  return texto.split(' ').length > 1 ? texto.replace(/^(atacando|moviéndose|disparando|cargando|huyendo|alto|en cuerpo a cuerpo|en retirada ordenada)( a la carrera| al paso)?$/, (m, o, marcha) => traducirTexto(o) + (marcha ? ' ' + traducirTexto(marcha.trim()) : '')) : traducirTexto(texto);
}
// factores de moral «cansancio −10, aliados huyendo cerca −8» (o cortados con «…» en el resumen)
function traducirFactores(texto) {
  return texto.split(', ').map(parte => { const m = /^(.+?) ([+−]\d+)(…?)$/.exec(parte); return m ? traducirTexto(m[1]) + ' ' + m[2] + m[3] : traducirTexto(parte.replace(/…$/, '')) + (parte.endsWith('…') ? '…' : ''); }).join(', ');
}
// trozos del detalle de una unidad: andanadas, orden, formación, terreno
function traducirParte(parte) {
  if (/^sin flechas \(cuerpo a cuerpo\)$/.test(parte)) return 'out of arrows (melee)';
  const andanadas = /^(\d+) andanadas$/.exec(parte); if (andanadas) return andanadas[1] + ' volleys';
  const orden = traducirOrden(parte); if (orden !== parte) return orden;
  const formacion = { 'línea': 'line', 'columna': 'column', cuadro: 'square', 'cuña': 'wedge', 'muro de escudos': 'shield wall', 'orden abierta': 'loose order' }[parte];
  return formacion || traducirTexto(parte);
}
